import sys as _mbsys; _mbsys.path.insert(0, 'C:\\Users\\Nanja\\MachineBench\\machinebench\\bridge'); import mb_cam as mb
import json

def run(_context):
    # Add adaptive2d roughing operation
    result = mb.add_operation(
        "Setup1",
        strategy="adaptive2d",
        tool=0,  # 1/2" 3Fl Carb TiCN Flat Endmill doc index 0
        geometry={"faces": [5], "type": "pocket"},
        name="Rough_Pocket_Adaptive"
    )
    op_name = result["operation"]
    print("Operation created:", op_name)

    # Print params - filter out non-serializable items
    params = result.get("params", {})
    safe_params = {}
    for k, v in params.items():
        try:
            # Try to get expression and value safely
            safe_params[k] = {
                "expression": str(v.get("expression", "")),
                "value": str(v.get("value", ""))
            }
        except Exception as e:
            safe_params[k] = {"error": str(e)}
    print("=== PARAMS ===")
    print(json.dumps(safe_params, indent=2))

